def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    dangerous_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 0) <= 4:
                    dangerous_prev.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    max_danger = max(dangerous_prev) if dangerous_prev else max_prev

    tight_supply = supply <= 17
    medium_supply = supply <= 20
    critical_me = hp <= 3 or no_water_days >= 2
    pressured_me = hp <= 5 or no_water_days >= 1

    if critical_me:
        target = max(90.0, max_danger + 3.0)
    elif tight_supply:
        target = max(72.0, max_danger + 2.0)
    elif pressured_me:
        target = max(54.0, min(max_prev * 0.7 + 8.0, max_prev + 1.5))
    elif medium_supply:
        if max_prev >= 120.0:
            target = 34.0
        else:
            target = max(38.0, min(60.0, max_prev * 0.55 + 6.0))
    else:
        if max_prev >= 120.0:
            target = 22.0
        elif max_prev >= 80.0:
            target = 28.0
        else:
            target = max(24.0, max_prev * 0.45 + 4.0)

    if day >= 8:
        target += 8.0
    elif day >= 6 and pressured_me:
        target += 5.0

    reserve = 0.0
    if hp > 5 and no_water_days == 0:
        reserve = 20.0
    elif hp > 3:
        reserve = 10.0

    affordable = max(0.0, budget - reserve)
    bid = min(target, affordable if affordable > 0 else budget)

    if pressured_me and bid < 35.0 and budget >= 35.0:
        bid = 35.0
    if critical_me and bid < 60.0 and budget >= 60.0:
        bid = 60.0

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents are alive, bid low to save budget.
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # If there are previous bids to react to
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # High competition detected (highest previous bid was aggressive)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # If healthy, let others overspend, bid conservatively.
            if my_status['hp'] > 3:
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            # If HP is critical, bid very aggressively to survive.
            return min(my_status['budget'], DAILY_SALARY * 0.95)
        # Moderate competition, try to win by slightly outbidding.
        return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

    # No previous bids (e.g., first day or all opponents didn't bid).
    # Bid based on personal HP.
    if my_status['hp'] <= 2:
        # Critical HP, bid high to ensure water.
        return min(my_status['budget'], DAILY_SALARY * 0.9)
    # Healthy, bid moderately.
    return min(my_status['budget'], DAILY_SALARY * 0.55)

